#!/usr/bin/env python3
"""Scoped, reversible ReShade Vulkan test for Ultimate Wine Toolbox 0.8.1."""
import argparse
import base64
import datetime
import hashlib
import json
import os
from pathlib import Path
import shlex
import shutil
import subprocess
import sys
import tempfile
import zlib

TEST_ID = "reshade-vulkan-test1"
HOOK = "toolbox/hooks/reshade-game-event.sh"
STATE = "state/reshade-vulkan-test.json"


def digest(data):
    return hashlib.sha256(data).hexdigest()


def write_atomic(path, data, mode=0o644):
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, name = tempfile.mkstemp(prefix=".uwt-reshade-vulkan-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(name, mode)
        os.replace(name, path)
    finally:
        Path(name).unlink(missing_ok=True)


def require_idle():
    for pattern in ("^(wineserver|wineserver64|wine|wine64|wine-preloader|wine64-preloader)$",
                    "[/]toolbox/ultimate-wine-toolbox.sh"):
        if subprocess.run(["pgrep", "-f" if pattern.startswith("[/]") else "-x", pattern],
                          stdout=subprocess.DEVNULL).returncode == 0:
            raise ValueError("Fermez les jeux Wine et la Toolbox avant installation/restauration.")


def unpack():
    data = zlib.decompress(base64.b64decode(PAYLOAD))
    if digest(data) != PAYLOAD_SHA256:
        raise ValueError("Le contenu de l’installateur est endommagé.")
    return json.loads(data)


def targets(home, hook, payload):
    return [(home / name, name) for name in payload["files"]] + [(hook, HOOK)]


def snapshot(path):
    if path.is_symlink() or (path.exists() and not path.is_file()):
        raise ValueError("Fichier non standard, aucune modification : " + str(path))
    if not path.exists():
        return {"data": None, "mode": None}
    return {"data": base64.b64encode(path.read_bytes()).decode(), "mode": path.stat().st_mode & 0o777}


def restore_entry(path, entry):
    if entry["data"] is None:
        path.unlink(missing_ok=True)
    else:
        write_atomic(path, base64.b64decode(entry["data"]), entry["mode"])


def install(home, hook):
    payload = unpack()
    if not (home / "VERSION").is_file() or (home / "VERSION").read_text().strip() != "0.8.1":
        raise ValueError("Ce test ciblé nécessite Ultimate Wine Toolbox 0.8.1. Aucun fichier modifié.")
    paths = targets(home, hook, payload)
    state_path = home / STATE
    if state_path.exists():
        state = json.loads(state_path.read_text())
        if state.get("test") == TEST_ID and all(
                not path.is_symlink() and path.is_file() and
                digest(path.read_bytes()) == digest(payload["files"][name].encode())
                for path, name in paths):
            print("Le test ReShade Vulkan est déjà installé. Les réglages sont conservés.")
            return
        raise ValueError("Un test ReShade Vulkan est déjà présent ou ses fichiers ont changé. Restaurez-le d’abord.")

    originals = {}
    for path, name in paths:
        entry = snapshot(path)
        actual = digest(base64.b64decode(entry["data"])) if entry["data"] is not None else None
        if actual not in payload["base_hashes"][name]:
            raise ValueError("Version différente détectée, aucun fichier modifié : " + str(path))
        originals[str(path)] = entry
    for name, content in payload["files"].items():
        if name.endswith(".sh"):
            result = subprocess.run(["bash", "-n"], input=content, text=True, capture_output=True)
            if result.returncode:
                raise ValueError("Syntaxe shell invalide : " + name)
        elif name.endswith(".py"):
            compile(content, name, "exec")

    backup = home / "state" / (TEST_ID + "-" + datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f"))
    backup.mkdir(parents=True)
    manifest = {"test": TEST_ID, "originals": originals, "installed": {}}
    for path, name in paths:
        manifest["installed"][str(path)] = digest(payload["files"][name].encode())
    write_atomic(backup / "backup.json", json.dumps(manifest, indent=2).encode())
    # Keep the tested installer itself available for offline rollback.
    shutil.copy2(Path(__file__).resolve(), backup / "restore.py")
    state = {"test": TEST_ID, "backup": str(backup), "hook": str(hook)}
    try:
        write_atomic(state_path, json.dumps(state, indent=2).encode())
        for path, name in paths:
            entry = originals[str(path)]
            mode = entry["mode"] if entry["mode"] is not None else 0o644
            if name.endswith(".sh"):
                mode |= 0o111
            write_atomic(path, payload["files"][name].encode(), mode)
    except BaseException:
        for path, entry in originals.items():
            restore_entry(Path(path), entry)
        state_path.unlink(missing_ok=True)
        raise
    print("Test ReShade Vulkan installé (base 0.8.1, version stable inchangée).")
    print("Menu : Ports → Ultimate Wine Toolbox → Outils et compatibilité → ReShade")
    print("Choisissez le jeu, Installer / modifier version et shaders, puis Vulkan natif sous Wine.")
    print("Sauvegarde : " + str(backup))
    print("Restauration hors ligne : python3 " + shlex.quote(str(backup / "restore.py")) + " --home " + shlex.quote(str(home)) + " --restore")


def restore_vulkan_games(home):
    configs = []
    for path in (home / "reshade/games").glob("*.json"):
        cfg = json.loads(path.read_text())
        if cfg.get("dll") == "vulkan":
            configs.append(cfg)
    if not configs:
        return
    sys.path.insert(0, str(home / "toolbox/helpers"))
    import reshade_manager
    for cfg in configs:
        reshade_manager.set_enabled(home, Path(cfg["rom"]), False)
    print("ReShade Vulkan désactivé pour les jeux concernés ; presets conservés.")


def restore(home):
    state_path = home / STATE
    if not state_path.exists():
        print("Aucun test ReShade Vulkan à restaurer.")
        return
    state = json.loads(state_path.read_text())
    manifest = json.loads((Path(state["backup"]) / "backup.json").read_text())
    if manifest.get("test") != TEST_ID:
        raise ValueError("Sauvegarde inattendue ; aucune modification.")
    # Do not overwrite subsequent code changes. Settings are expected to change.
    for name, expected in manifest["installed"].items():
        path = Path(name)
        if path.is_symlink() or not path.is_file() or digest(path.read_bytes()) != expected:
            raise ValueError("Un fichier a changé depuis le test ; restauration arrêtée : " + name)
    restore_vulkan_games(home)
    before = {name: snapshot(Path(name)) for name in manifest["originals"]}
    try:
        for name, entry in manifest["originals"].items():
            restore_entry(Path(name), entry)
    except BaseException:
        for name, entry in before.items():
            restore_entry(Path(name), entry)
        raise
    state_path.unlink()
    print("Fichiers et réglages ReShade Vulkan antérieurs restaurés. Sauvegarde conservée.")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--home", type=Path, default=Path("/userdata/system/ultimate-wine-toolbox"))
    parser.add_argument("--hook", type=Path, default=Path("/userdata/system/scripts/ultimate-wine-toolbox-reshade.sh"))
    parser.add_argument("--restore", action="store_true")
    args = parser.parse_args()
    try:
        if os.geteuid() != 0:
            raise ValueError("Lancez cet installateur en root sur Batocera.")
        require_idle()
        if args.restore:
            restore(args.home.resolve())
        else:
            install(args.home.resolve(), args.hook.absolute())
    except (ValueError, OSError) as error:
        print("ERREUR : " + str(error), file=sys.stderr)
        return 1
    return 0


# Embedded UTF-8 source files, baseline SHA-256 hashes and payload checksum.
# Generated from the scoped feature commit; no download occurs during install.
PAYLOAD_SHA256 = '0f68cbf2d8abe2b8247e8bbacb6daae0f9a50e926aca1a987f532a367ea5f44b'
PAYLOAD = ''

if __name__ == "__main__":
    sys.exit(main())
